CREATE TABLE IF NOT EXISTS admin_users(id bigserial PRIMARY KEY,username text NOT NULL UNIQUE,display_name text NOT NULL DEFAULT 'Pemilik Kos',password_hash text NOT NULL,must_change_password boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_admin_users_username_ci ON admin_users(lower(username));
CREATE TABLE IF NOT EXISTS app_settings(id smallint PRIMARY KEY DEFAULT 1 CHECK(id=1),boarding_name text NOT NULL DEFAULT 'Kos Digital',address text NOT NULL DEFAULT '',monthly_price integer NOT NULL DEFAULT 0 CHECK(monthly_price>=0),initial_price integer NOT NULL DEFAULT 0 CHECK(initial_price>=0),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO app_settings(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS rooms(id bigserial PRIMARY KEY,room_number text NOT NULL UNIQUE,monthly_price integer CHECK(monthly_price IS NULL OR monthly_price>=0),notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenants(id bigserial PRIMARY KEY,full_name text NOT NULL,username text NOT NULL UNIQUE,password_hash text NOT NULL,room_id bigint REFERENCES rooms(id) ON DELETE SET NULL,phone text NOT NULL DEFAULT '',monthly_rent integer NOT NULL DEFAULT 0 CHECK(monthly_rent>=0),contract_start date,contract_end date,is_active boolean NOT NULL DEFAULT true,must_change_password boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenants_username_ci ON tenants(lower(username)); CREATE INDEX IF NOT EXISTS idx_tenants_room_id ON tenants(room_id);
CREATE TABLE IF NOT EXISTS payments(id bigserial PRIMARY KEY,tenant_id bigint NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,payment_type text NOT NULL CHECK(payment_type IN ('initial','extension')),months integer NOT NULL DEFAULT 1 CHECK(months BETWEEN 1 AND 12),amount integer NOT NULL CHECK(amount>=0),period_start date NOT NULL,period_end date NOT NULL,status text NOT NULL DEFAULT 'unpaid' CHECK(status IN ('unpaid','pending','paid','failed','expired')),provider text NOT NULL DEFAULT 'manual',order_id text UNIQUE,transaction_id text,qr_image_data text,qr_expires_at timestamptz,paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_payments_tenant_created ON payments(tenant_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status);
CREATE TABLE IF NOT EXISTS complaints(id bigserial PRIMARY KEY,tenant_id bigint NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,title text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'menunggu' CHECK(status IN ('menunggu','diproses','selesai')),admin_note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_complaints_status ON complaints(status,created_at DESC);
CREATE TABLE IF NOT EXISTS login_attempts(id bigserial PRIMARY KEY,username text NOT NULL,ip_address text NOT NULL,role text NOT NULL,succeeded boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_login_attempts_lookup ON login_attempts(username,ip_address,role,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_role text NOT NULL,actor_id bigint,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());